  // Count labels belong to a text-session ID. Text Region Detection can create
  // multiple sessions for the same container session, so prefer the exact
  // session used by Container Count Classification, then select another linked
  // session only when it actually contains saved 2-container labels.
  const preferredIds=[storedCount,localStorage.getItem('cl-casting-hole-session'),storedText].filter(Boolean);
  const withLabels=await Promise.all(candidates.map(async item=>{
   try{const result=await api(`/api/text-sessions/${item.id}/container-counts?status=all&offset=0&limit=1`);return{item,two:Number(result.counts?.['2']||0),crops:Number(result.total||0)}}catch{return{item,two:0,crops:0}}
  }));
