async function loadRecords(){records.clear();if(task==='count'){let off=0;for(;;){const page=await api(`/api/text-sessions/${sid}/container-counts?status=all&offset=${off}&limit=1000`);for(const item of page.items)records.set(item.path,item);if(off+page.items.length>=page.total)break;off+=page.items.length}return}let off=0;for(;;){const page=await api(`/api/${sessionPath()}/${sid}/images?status=all&offset=${off}&limit=1000`);for(const x of page.items)records.set(x.path,x);if(off+page.items.length>=page.total)break;off+=page.items.length}}
