async function resume(){const list=await api(`/api/${sessionPath()}`);if(!list.length){note('No saved session for this task yet. Choose an image folder to create one.');return}let pick=list[0];if(list.length>1){const choice=prompt(`Enter the session number to resume for ${task==='text'?'Text Region Detection':'Container Detection'}:\n`+list.map((session,i)=>`${i+1}. ${session.root_name} (${session.image_count} images)`).join('\n'),'1');if(!choice)return;pick=list[Math.max(0,Math.min(list.length-1,(+choice||1)-1))]}const sessionKey=localStorage.getItem(`cl-server-mode:${pick.id}`)==='true'?(task==='text'?'cl-server-text-session':'cl-server-session'):taskSessionKey();localStorage.setItem(sessionKey,pick.id);sid=pick.id;if(localStorage.getItem(`cl-server-mode:${pick.id}`)==='true'){await startSession(await serverRoot(),{resumeSession:true});return}const saved=await restoreHandle(task==='text'?`text-root:${pick.id}`:'root');if(!saved){note('Saved session metadata is available. Re-select its local folder to grant browser file access.',true);return}if(await saved.queryPermission({mode:'read'})!=='granted'&&await saved.requestPermission({mode:'read'})!=='granted'){note('Folder permission was not granted. Re-select the source folder.',true);return}if(task==='text'){const handleKey=localStorage.getItem(`${sessionKey}-server`)==='true'?'cl-server':'cl-local';localStorage.setItem(`${handleKey}-container-session:${saved.name}`,localStorage.getItem(`${handleKey}-container-session:${saved.name}`)||localStorage.getItem('cl-session')||'')}await startSession(saved,{resumeSession:true})}
