const initialZoom=Number(localStorage.getItem('cl-casting-initial-zoom'))||150;$('castingInitialZoom').value=initialZoom;const initialTask=task;task='container';$('taskSelector').value=['text','count','casting'].includes(initialTask)?initialTask:'container';switchTask(initialTask);$('taskSelector').onchange=e=>{const next=e.target.value;switchTask(next);serverRoot().then(handle=>startSession(handle)).catch(error=>note(`Server dataset unavailable: ${error.message}`,true))};$('textExportYolo').onclick=exportTextYolo;$('castingInitialZoom').onchange=()=>{const value=Math.max(50,Math.min(500,Number($('castingInitialZoom').value)||150));$('castingInitialZoom').value=value;localStorage.setItem('cl-casting-initial-zoom',String(value));if(task==='casting'&&img)fit(value/100)};$('castingAuto').onclick=autoLabelCastingHoles;$('castingExport').onclick=exportCastingHole;$('castingSave').onclick=saveCastingHole;$('castingSkip').onclick=skipCastingHole;$('countOne').onclick=()=>setContainerCount(1);$('countTwo').onclick=()=>setContainerCount(2);$('countExport').onclick=exportContainerCounts;$('countPageSize').onchange=async()=>{countPageSize=Number($('countPageSize').value);await loadCountPage(0)};$('countPrevPage').onclick=()=>loadCountPage(countPageIndex-1);$('countNextPage').onclick=()=>loadCountPage(countPageIndex+1);$('countSelectPage').onchange=()=>{for(const item of countItems)$('countSelectPage').checked?countSelection.add(item.path):countSelection.delete(item.path);renderCountGrid()};$('countClearSelection').onclick=()=>{countSelection.clear();renderCountGrid()};$('countBulkOne').onclick=()=>bulkSetCount(1);$('countBulkTwo').onclick=()=>bulkSetCount(2);$('countImageClose').onclick=()=> $('countImageDialog').close();$('verifyText').onclick=()=>saveTextAnnotation('verified',{advance:true});$('rejectText').onclick=rejectTextImage;
$('filter').onchange=async()=>{queueFilter=$('filter').value;if(task==='count')await loadCountPage(0);else{const list=currentEntries(),active=entries[current]?.path;if(!list.length)current=-1;else if(!list.some(item=>item.path===active))current=entries.findIndex(item=>item.path===list[0].path);await showCurrent()}};$('queueList').onchange=async()=>{const path=$('queueList').value;if(!path)return;current=entries.findIndex(x=>x.path===path);await showCurrent()};$('verify').onclick=verify;$('reject').onclick=reject;$('undoReject').onclick=undoReject;$('prev').onclick=()=>seek(-1);$('next').onclick=()=>seek(1);$('fit').onclick=()=>fit();$('reset').onclick=()=>fit();$('plus').onclick=()=>fit(viewZoom*1.2);$('minus').onclick=()=>fit(viewZoom/1.2);$('undo').onclick=undo;$('redo').onclick=redo;$('del').onclick=()=>{if(selected>=0&&!cropMode){pushUndo();boxes.splice(selected,1);selected=-1;if(task==='text')textDirty=true;if(task==='casting')castingDirty=true;draw();saveCropDraft();renderStatus();scheduleTextAutosave()}};$('cropToggle').onclick=toggleCrop;$('applyCrop').onclick=applyCrop;$('cancelCrop').onclick=cancelCrop;$('resetCrop').onclick=resetCrop;$('export').onclick=exportProgress;
$('permanent').onchange=e=>{if(e.target.checked&&!confirm('Permanent deletion permanently removes rejected images and matching .txt files from the selected folder. This cannot be undone. Enable it?'))e.target.checked=false};
async function validateLabels(){if(task==='text')return note('Use the text-region YOLO export to download verified class-0 annotations.');if(!root){note('Choose a local folder first.',true);return}const issues=[];for(let i=0;i<entries.length;i++){const source=entries[i].path,rec=records.get(source),path=rec?.derivative_path||source,label=await labelPathFor(path);if(rec?.derivative_path&&!await fileExists(path)){issues.push({path,issue:'missing cropped image derivative'});continue}let text;try{text=await(await(await entryFor(label)).getFile()).text()}catch(e){if(e.name==='NotFoundError')issues.push({path,issue:'missing label'});else issues.push({path,issue:`cannot read label: ${e.message}`});continue}const lines=text.trim().split(/\r?\n/).filter(Boolean);if(!lines.length){issues.push({path,issue:'empty label'});continue}for(const [n,line]of lines.entries()){const a=line.trim().split(/\s+/).map(Number);if(a.length!==5||a.some(v=>!Number.isFinite(v))||a[0]<0||!a.slice(1).every(v=>v>=0&&v<=1)||a[3]<=0||a[4]<=0||a[1]-a[3]/2<0||a[2]-a[4]/2<0||a[1]+a[3]/2>1||a[2]+a[4]/2>1)issues.push({path,issue:`invalid coordinates at line ${n+1}`})}}
const result={checked:entries.length,issues};const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='container-label-validation.json';a.click();URL.revokeObjectURL(a.href);note(`Validation checked ${entries.length} images and found ${issues.length} issue(s). Report downloaded.`)}
async function exportYolo(){if(task==='text')return exportTextYolo();if(!root)return note('Server dataset is not loaded.',true);if(serverMode){const result=await api(`/api/sessions/${sid}/export`);return note('Container progress export requested.')}if(!('showDirectoryPicker'in window))return;try{const dest=await showDirectoryPicker({id:'container-yolo-export',mode:'readwrite'});for(const e of entries){const rec=records.get(e.path);if(rec?.status!=='verified')continue;const fromImage=rec.derivative_path||e.path,label=await labelPathFor(fromImage),imageOut=fromImage.startsWith('images/')?fromImage:`images/${fromImage}`,labelOut=label.startsWith('labels/')?label:`labels/${label}`;for(const [from,to]of [[fromImage,imageOut],[label,labelOut]]){const f=await(await entryFor(from)).getFile();let d=dest;for(const part of to.split('/').slice(0,-1))d=await d.getDirectoryHandle(part,{create:true});const out=await d.getFileHandle(to.split('/').at(-1),{create:true}),w=await out.createWritable();await w.write(await f.arrayBuffer());await w.close()}}note('YOLO export complete in the selected folder.')}catch(e){if(e.name!=='AbortError')note(`YOLO export failed: ${e.message}`,true)}}
async function exportTextYolo(){if(!root)return note('Server dataset is not loaded.',true);if(serverMode){let exported=0;for(const e of entries){const rec=records.get(e.path);if(rec?.status!=='verified'||!e.cachedCropPath)continue;const source=await(await entryFor(e.cachedCropPath)).getFile(),label=TextRegion.formatYoloBoxes(rec.boxes);const imageOut=`images/${e.path}.png`,labelOut=`labels/${e.path}.txt`;for(const [path,data]of [[imageOut,await source.arrayBuffer()],[labelOut,label]])await api(`/api/server-dataset/file?path=${encodeURIComponent(path)}`,{method:'PUT',headers:{'Content-Type':'application/octet-stream'},body:data});exported++}return note(`Text-region YOLO export complete: ${exported} verified container crops saved on the server.`)}if(!('showDirectoryPicker'in window))return note('YOLO export needs Chrome or Edge on localhost/HTTPS.',true);try{const dest=await showDirectoryPicker({id:'container-number-yolo-export',mode:'readwrite'}),writtenLabels=new Set();let exported=0;for(const e of entries){const rec=records.get(e.path);if(rec?.status!=='verified')continue;const blob=serverMode&&e.cachedCropPath?await(await entryFor(e.cachedCropPath)).getFile():await croppedEntryBlob(e),base=e.path.replace(/[^a-zA-Z0-9._/-]/g,'_'),imageOut=`images/${base}.png`,labelOut=`labels/${base}.txt`;if(writtenLabels.has(labelOut))throw Error(`Two container boxes map to the same YOLO label path: ${labelOut}`);writtenLabels.add(labelOut);await writeExportFile(dest,imageOut,blob);await writeExportFile(dest,labelOut,new Blob([TextRegion.formatYoloBoxes(rec.boxes)],{type:'text/plain'}));exported++}note(`Text-region YOLO export complete: ${exported} verified container-box crop(s) copied with class 0 container_number labels.`)}catch(error){if(error.name!=='AbortError')note(`Text-region YOLO export failed: ${error.message}`,true)}}
async function croppedEntryBlob(e){const file=await(await entryFor(e.sourcePath)).getFile(),bitmap=await createImageBitmap(file);try{const rect=TextRegion.cropRect(e.containerBox,bitmap.width,bitmap.height),canvas=document.createElement('canvas');canvas.width=rect.width;canvas.height=rect.height;canvas.getContext('2d').drawImage(bitmap,rect.x,rect.y,rect.width,rect.height,0,0,rect.width,rect.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Could not encode cropped container image')),'image/png'))}finally{bitmap.close()}}
async function writeExportFile(dest,path,blob){let dir=dest;for(const part of path.split('/').slice(0,-1))dir=await dir.getDirectoryHandle(part,{create:true});const file=await dir.getFileHandle(path.split('/').at(-1),{create:true}),writer=await file.createWritable();await writer.write(blob);await writer.close()}
$('validate').onclick=validateLabels;$('exportYolo').onclick=exportYolo;
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)){if(e.key==='Escape')document.activeElement.blur();return}if(e.code==='Space'){space=true;e.preventDefault()}if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();undo()}else if(e.ctrlKey&&e.key.toLowerCase()==='y'){e.preventDefault();redo()}else if(e.repeat)return;else if(e.key.toLowerCase()==='v')verify();else if(e.key.toLowerCase()==='r'&&task==='container')reject();else if(e.key==='ArrowLeft')seek(-1);else if(e.key==='ArrowRight')seek(1);else if((e.key==='Delete'||e.key==='Backspace')&&!cropMode)$('del').click();else if(e.key.toLowerCase()==='f')fit();else if(e.key==='Escape'){if(cropMode)cancelCrop();else if(mode==='draw'){mode='';start=null;draw()}else selected=-1,draw()}});window.addEventListener('keyup',e=>{if(e.code==='Space')space=false});window.addEventListener('blur',()=>space=false);
